    data = sys.stdin.read().split()
    q, ttl = int(data[0]), int(data[1])
    pos = 2
    exp = {}
    heap = []
    out = []
    for _ in range(q):
        op = data[pos]
        if op == 'count':
            t = int(data[pos + 1])
            pos += 2
            while heap and heap[0][0] <= t:
                e, tok = heapq.heappop(heap)
                if exp.get(tok) == e:
                    del exp[tok]
            out.append(len(exp))
        else:
            tok, t = data[pos + 1], int(data[pos + 2])
            pos += 3
            while heap and heap[0][0] <= t:
                e, k = heapq.heappop(heap)
                if exp.get(k) == e:
                    del exp[k]
            if op == 'generate':
                exp[tok] = t + ttl
                heapq.heappush(heap, (t + ttl, tok))
            elif tok in exp:
                exp[tok] = t + ttl
                heapq.heappush(heap, (t + ttl, tok))
    print('\n'.join(map(str, out)))

