def gen(rng):
    alpha = 'abcdefghijklmnopqrstuvwxyz0123456789'
    def make(q, ttl, step_max, p_gen, p_renew, id_len=(1, 3)):
        ops = []
        t = 0
        ids = []
        used = set()
        def newid():
            while True:
                s = ''.join(rng.choice(alpha) for _ in range(rng.randint(*id_len)))
                if s not in used:
                    used.add(s)
                    return s
        for k in range(q):
            t += rng.randint(1, step_max)
            r = rng.random()
            if k == q - 1:
                ops.append('count %d' % t)
            elif r < p_gen:
                s = newid()
                ids.append(s)
                ops.append('generate %s %d' % (s, t))
            elif r < p_gen + p_renew:
                if ids and rng.random() < 0.9:
                    ops.append('renew %s %d' % (rng.choice(ids), t))
                else:
                    ops.append('renew %s %d' % (newid(), t))
            else:
                ops.append('count %d' % t)
        return '%d %d\n' % (q, ttl) + '\n'.join(ops)
    tests = ['3 5\ngenerate a 1\nrenew a 5\ncount 6', '1 1\ncount 1', '2 4\ngenerate zz 10\ncount 14',
             '3 4\ngenerate zz 10\ncount 13\ncount 14',
             '7 5\ngenerate aaa 1\nrenew aaa 2\ngenerate bbb 3\ncount 6\ncount 7\nrenew aaa 8\ncount 8']
    for q in (4, 6, 8, 12, 16, 25):
        for _ in range(4):
            tests.append(make(q, rng.randint(1, 8), rng.choice([1, 2, 4]), rng.choice([0.3, 0.5]), rng.choice([0.2, 0.35])))
    # large tests
    N = 100000
    ops = []
    ids = []
    for i in range(50000):
        s = 'u%d' % i
        ids.append(s)
        ops.append('generate %s %d' % (s, i + 1))
    t = 50000
    for k in range(50000):
        t += rng.randint(1, 100)
        if k % 5 == 0:
            ops.append('renew %s %d' % (rng.choice(ids), t))
        else:
            ops.append('count %d' % t)
    tests.append('%d %d\n' % (N, 10**9) + '\n'.join(ops))
    tests.append(make(N, 3000, 100, 0.4, 0.3, (3, 8)))
    tests.append(make(N, 10**9, 1000, 0.5, 0.2, (3, 8)))
    tests.append(make(N, 50, 20, 0.45, 0.25, (4, 8)))
    return tests

